module firr42_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    reg  [15:0] p  [0:41];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 * x + 5;
            for (i = 1; i < 42; i = i + 1) p[i] <= 8'd2 * xs[i] + 5;
            y <= p[41];
        end
    end
endmodule

